namespace Aegis.Studio.Domain.Galleries;
public sealed class ProductionAssignment{private ProductionAssignment(){} public ProductionAssignment(Guid mediaAssetId,Guid workspaceId,string assignedTo,string activity){Id=Guid.NewGuid();MediaAssetId=mediaAssetId;WorkspaceId=workspaceId;AssignedTo=assignedTo.Trim();Activity=activity.Trim();Status="Open";StartedUtc=DateTimeOffset.UtcNow;} public Guid Id{get;private set;} public Guid MediaAssetId{get;private set;} public Guid WorkspaceId{get;private set;} public string AssignedTo{get;private set;}=string.Empty; public string Activity{get;private set;}=string.Empty; public string Status{get;private set;}=string.Empty; public DateTimeOffset StartedUtc{get;private set;} public DateTimeOffset? CompletedUtc{get;private set;} public void Complete(){Status="Completed";CompletedUtc=DateTimeOffset.UtcNow;}}
